<div class="flex h-full min-h-0 flex-col bg-surface">
    <div class="flex h-20 shrink-0 items-center justify-between border-b border-border-subtle px-5"><div><h2 class="font-heading text-sm font-bold text-ink-950">Research context</h2><p class="mt-0.5 text-xs text-ink-500">Records behind this response</p></div><button type="button" @click="contextOpen = false; contextDrawerOpen = false" class="counselor-icon-button" aria-label="Close research context"><x-icon name="x" class="size-4" /></button></div>
    <div class="min-h-0 flex-1 space-y-7 overflow-y-auto overscroll-contain p-5 safe-area-bottom">
        <section x-show="contextCards.length"><h3 class="mb-3 text-[11px] font-semibold uppercase tracking-wider text-ink-500">Referenced universities</h3><template x-for="card in contextCards" :key="card.id"><a :href="card.profile_url" class="mb-2 block rounded-xl border border-border-default p-3 hover:border-brand-300"><span class="block text-sm font-semibold leading-snug text-ink-900" x-text="card.name"></span><span class="mt-1 block text-xs text-ink-500" x-text="card.city + ' · ' + card.sector"></span></a></template></section>
        <section x-show="contextSources.length"><h3 class="mb-3 text-[11px] font-semibold uppercase tracking-wider text-ink-500">Source details</h3><template x-for="(source, index) in contextSources" :key="source.url"><article class="mb-3 rounded-xl border border-border-default p-3"><span class="text-xs font-semibold text-brand-700" x-text="'Source ' + (index + 1)"></span><h4 class="mt-1 text-sm font-semibold leading-snug text-ink-900" x-text="source.title"></h4><p class="mt-2 text-xs text-ink-600" x-text="source.university"></p><p class="mt-1 text-xs text-ink-500" x-text="humanize(source.context) + ' · ' + humanize(source.status)"></p><p class="mt-2 text-xs text-ink-500" x-text="source.verified_at ? 'Last checked ' + formatDate(source.verified_at) : 'Verification date unavailable'"></p><p x-show="source.outdated" class="mt-2 text-xs font-medium text-warning-700">This source needs a freshness review.</p><a :href="source.url" target="_blank" rel="noopener noreferrer" class="mt-2 inline-flex min-h-11 items-center gap-2 text-xs font-semibold text-brand-700">Open official source<x-icon name="external-link" class="size-3.5" /></a></article></template></section>
        <p x-show="!contextSources.length" class="text-sm leading-relaxed text-ink-600">No source references are recorded for this response.</p>
        <p class="text-xs leading-relaxed text-ink-500">A registry listing does not establish current program accreditation, admission availability or eligibility. Confirm decisions with the institution.</p>
    </div>
</div>
